use std::{
    collections::{BTreeSet, HashMap},
    fmt,
    time::Instant,
};

use zenoh_protocol::transport::TransportSn;
use zenoh_result::ZResult;

use super::seq_num::SeqNum;

/// Where a received number stands after the last number delivered.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Position {
    /// Right after the last: deliverable now.
    Next,
    /// Further ahead, within half the resolution, and not held yet: kept until the gap fills.
    Ahead,
    /// Delivered already, held already, or more than half the resolution ahead.
    Old,
}

/// Keeping an item would take the held sizes past the hold's bound.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Overflow;

struct Entry<T> {
    item: T,
    size: usize,
    at: Instant,
}

/// The items of one channel that arrived ahead of a gap in their numbers. They are held until
/// the gap fills and released in number order, as RFC 8684 reassembles a connection's data by
/// its data sequence number across subflows.
pub(crate) struct Hold<T> {
    max_held_size: usize,
    held_size: usize,
    items: HashMap<TransportSn, Entry<T>>,
    // The held items by arrival, oldest first: the first is the age of the current gap.
    arrivals: BTreeSet<(Instant, TransportSn)>,
}

impl<T> Hold<T> {
    pub(crate) fn new(max_held_size: usize) -> Hold<T> {
        Hold {
            max_held_size,
            held_size: 0,
            items: HashMap::new(),
            arrivals: BTreeSet::new(),
        }
    }

    /// Where `sn` stands after `last`, the last number delivered.
    pub(crate) fn position(&self, last: &SeqNum, sn: TransportSn) -> ZResult<Position> {
        let gap = last.gap(sn)?;
        // Within half the resolution ahead, as `SeqNum::roll` accepts it.
        let ahead = gap != 0 && (gap & !(last.resolution() >> 1)) == 0;
        Ok(if gap == 1 {
            Position::Next
        } else if ahead && !self.items.contains_key(&sn) {
            Position::Ahead
        } else {
            Position::Old
        })
    }

    /// Keeps an item ahead of a gap. Err(Overflow) when the held sizes would pass the bound.
    pub(crate) fn keep(
        &mut self,
        sn: TransportSn,
        item: T,
        size: usize,
        now: Instant,
    ) -> Result<(), Overflow> {
        // position() calls a held number Old, so a number is never kept twice.
        debug_assert!(!self.items.contains_key(&sn), "number {sn} kept twice");
        if self.items.contains_key(&sn) {
            return Ok(());
        }
        let held_size = self.held_size.saturating_add(size);
        if held_size > self.max_held_size {
            return Err(Overflow);
        }
        self.held_size = held_size;
        self.items.insert(
            sn,
            Entry {
                item,
                size,
                at: now,
            },
        );
        self.arrivals.insert((now, sn));
        Ok(())
    }

    /// The held item numbered right after `last`, advancing `last` past it.
    pub(crate) fn next_ready(&mut self, last: &mut SeqNum) -> Option<T> {
        let sn = last.next();
        let held = self.items.remove(&sn)?;
        self.arrivals.remove(&(held.at, sn));
        self.held_size -= held.size;
        last.increment();
        Some(held.item)
    }

    /// The earliest arrival among the items still held: the age of the current gap.
    pub(crate) fn since(&self) -> Option<Instant> {
        self.arrivals.first().map(|(at, _)| *at)
    }

    /// The sizes of the items held, added up.
    pub(crate) fn held_size(&self) -> usize {
        self.held_size
    }
}

impl<T> fmt::Debug for Hold<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Hold")
            .field("held", &self.items.len())
            .field("held_size", &self.held_size)
            .field("max_held_size", &self.max_held_size)
            .finish()
    }
}

#[cfg(test)]
mod tests {
    use std::time::{Duration, Instant};

    use zenoh_protocol::core::Bits;

    use super::*;

    fn last_sn(sn: TransportSn) -> SeqNum {
        SeqNum::make(sn, Bits::U32).unwrap()
    }

    #[test]
    fn an_item_numbered_after_the_last_is_next() {
        let hold = Hold::<()>::new(1_000);
        assert_eq!(hold.position(&last_sn(1), 2).unwrap(), Position::Next);
    }

    #[test]
    fn items_read_in_reverse_are_released_in_order() {
        let mut hold = Hold::new(1_000);
        let mut last = last_sn(0);
        let now = Instant::now();
        for sn in [5, 4, 3, 2] {
            assert_eq!(hold.position(&last, sn).unwrap(), Position::Ahead);
            hold.keep(sn, sn, 1, now).unwrap();
        }
        assert_eq!(hold.position(&last, 1).unwrap(), Position::Next);
        assert!(last.roll(1).unwrap());
        let released: Vec<_> = std::iter::from_fn(|| hold.next_ready(&mut last)).collect();
        assert_eq!(released, [2, 3, 4, 5]);
        assert_eq!(hold.next_ready(&mut last), None);
        assert_eq!(last.get(), 5);
    }

    #[test]
    fn a_number_held_or_delivered_is_old() {
        let mut hold = Hold::new(1_000);
        let last = last_sn(1);
        hold.keep(3, (), 1, Instant::now()).unwrap();
        assert_eq!(hold.position(&last, 3).unwrap(), Position::Old);
        assert_eq!(hold.position(&last, 1).unwrap(), Position::Old);
        assert_eq!(hold.position(&last, 0).unwrap(), Position::Old);
    }

    #[test]
    fn numbers_across_the_wrap_are_released_in_order() {
        // Bits::U8 numbers run from 0 to 127.
        let mut hold = Hold::new(1_000);
        let mut last = SeqNum::make(125, Bits::U8).unwrap();
        let now = Instant::now();
        for sn in [1, 0, 127] {
            assert_eq!(hold.position(&last, sn).unwrap(), Position::Ahead);
            hold.keep(sn, sn, 1, now).unwrap();
        }
        assert_eq!(hold.position(&last, 126).unwrap(), Position::Next);
        assert!(last.roll(126).unwrap());
        let released: Vec<_> = std::iter::from_fn(|| hold.next_ready(&mut last)).collect();
        assert_eq!(released, [127, 0, 1]);
    }

    #[test]
    fn keeping_past_the_size_bound_overflows() {
        let mut hold = Hold::new(10);
        let mut last = last_sn(1);
        let now = Instant::now();
        assert_eq!(hold.keep(3, 3, 6, now), Ok(()));
        assert_eq!(hold.keep(4, 4, 6, now), Err(Overflow));
        assert!(last.roll(2).unwrap());
        assert_eq!(hold.next_ready(&mut last), Some(3));
        assert_eq!(hold.keep(4, 4, 6, now), Ok(()));
    }

    #[test]
    fn the_gap_is_as_old_as_its_oldest_held_item() {
        let mut hold = Hold::new(1_000);
        let mut last = last_sn(1);
        let t0 = Instant::now();
        let t1 = t0 + Duration::from_millis(1);
        hold.keep(3, 3, 1, t0).unwrap();
        hold.keep(5, 5, 1, t1).unwrap();
        assert_eq!(hold.since(), Some(t0));
        // 2 fills the first gap and releases 3.
        assert!(last.roll(2).unwrap());
        assert_eq!(hold.next_ready(&mut last), Some(3));
        assert_eq!(hold.next_ready(&mut last), None);
        assert_eq!(hold.since(), Some(t1));
        // 4 fills the second gap and releases 5.
        assert!(last.roll(4).unwrap());
        assert_eq!(hold.next_ready(&mut last), Some(5));
        assert_eq!(hold.since(), None);
    }
}
